INSERT INTO "notas_templates" ("id", "usuario_id", "atalho", "titulo_secao", "grupo", "cor_secao", "conteudo", "is_global", "ordem", "data_criacao") VALUES
(1, NULL, '/abertura', 'INÍCIO ATENDIMENTO', NULL, '#22c55e', 'Boa noite a todos!\nSou o agente {AGENTE} e informo que amanhã {DATA} estarei a cargo do apoio técnico na Troca de Turma no Aeroporto de Cabo Frio.\nQualquer dúvida ou alteração, favor entrar em contato.', 1, 0, '2026-05-15 00:58:17'),
(2, NULL, '/saida', 'SAÍDA HOTEL', NULL, '#3b82f6', 'Prezados,\nInformo que os colaboradores listados abaixo deixaram o {HOTEL} e seguiram para o Aeroporto de Cabo Frio:\n\n{EMPRESA}\n1. \n2. \n3. ', 1, 1, '2026-05-15 00:58:17'),
(3, NULL, '/recepcao', 'RECEPÇÃO', NULL, '#06b6d4', 'Prezados(a);\nInformo que os colaboradores listados abaixo foram recepcionados no Aeroporto de Cabo Frio:\n\n{EMPRESA}\n1. ', 1, 2, '2026-05-15 00:58:17'),
(4, NULL, '/checkin', 'CHECK-IN & BRIEFING', NULL, '#8b5cf6', 'Bom dia a todos!\nPrezados,\nInformo que os colaboradores do vôo das {HORARIO}, listados abaixo concluíram o check-in e briefing às {HORA_BRIEFING}.\n\n{EMPRESA}\n1. \n\nNão houve entrega/envio de documentação ou material para os colaboradores ou para bordo.\nEMPRESA AÉREA: {CIA}\nMODELO AERONAVE: {MODELO}\nPREFIXO: {PREFIXO}', 1, 3, '2026-05-15 00:58:17'),
(5, NULL, '/embarque', 'PORTÃO DE EMBARQUE', NULL, '#f59e0b', 'Prezados,\nPortão de embarque: {HORA}\nModelo Aeronave: {MODELO}\nPrefixo: {PREFIXO}', 1, 4, '2026-05-15 00:58:17'),
(6, NULL, '/decolagem', 'DECOLAGEM', NULL, '#ef4444', 'Prezados,\nDecolagem: {HORA}\nCIA: {CIA}\nPrefixo: {PREFIXO}', 1, 5, '2026-05-15 00:58:17'),
(7, NULL, '/retorno', 'RETORNO', NULL, '#a855f7', 'Prezados,\nInformo que o vôo está em retorno ao Aeroporto de Cabo Frio.\nPrevisão de pouso: {HORA}\nCIA: {CIA}\nPrefixo: {PREFIXO}', 1, 6, '2026-05-15 00:58:17'),
(8, NULL, '/pouso', 'POUSO', NULL, '#10b981', 'Prezados,\nInformo que a aeronave pousou às {HORA}.\nCIA: {CIA}\nPrefixo: {PREFIXO}', 1, 7, '2026-05-15 00:58:17'),
(9, NULL, '/final', 'POUSO & FINALIZAÇÃO', NULL, '#16a34a', 'Prezados,\nInformo que a troca foi finalizada com êxito às {HORA}.\n\n{EMPRESA}\n1. \n\nApós desembarque os colaboradores seguiram para seus respectivos destinos.\n           * Atendimento finalizado *', 1, 8, '2026-05-15 00:58:17');
INSERT INTO "notificacoes" ("id", "titulo", "mensagem", "tipo", "ativa", "regra_exibicao", "validade_dias", "data_criacao", "mostrar_feedback") VALUES
(3, 'Lançamento da Nova Versão do Sistema Gerador de Relatórios', 'Olá a todos!\r\n\r\nO nosso Gerador de Relatórios foi atualizado com um mecanismo muito mais moderno! 🚀\r\n\r\nConfira as novidades:\r\n\r\nCriação de contas: Agora você pode criar um perfil para salvar seus documentos.\r\n\r\nHistórico e Edição: Acesse, visualize novamente e edite os relatórios que você já gerou.\r\n\r\nDeixem suas opiniões e sugestões de novas funcionalidades. \r\nO feedback de vocês é muito importante!\r\n\r\nObrigado a todos que utilizam o portal!', 'aviso', 0, 'uma_vez', 7, '2026-05-04 12:34:58', 1),
(5, '[Aviso] Instabilidade temporária no Gerador de Relatórios', 'Pessoal, bom dia!\r\n\r\nOntem precisei fazer um ajuste no sistema de relatórios e isso acabou gerando um bug: no momento, não é possível visualizar o documento após fazer o download ou o compartilhamento.\r\n\r\nJá estou trabalhando nisso e acredito que até a parte da tarde o problema estará resolvido.\r\nPeço para avisarem lá no grupo de TT assim que estiver tudo 100% normalizado, combinado?', 'aviso', 0, 'sempre', 7, '2026-05-05 13:30:58', 0),
(7, 'Sistema funcionando novamente!', 'Bom dia pessoal!\r\n\r\nResolvi o bug somente agora na parte da noite 05/05/2026 - 22:30h, deu bastante trabalho, não sei oq aconteceu mas precisei reescrever toda a lógica da página de geração de PDF.\r\n\r\nNo momento só está sendo possível gerar relatórios caso estejam logados, quem não tiver conta é só criar uma e entrar que funciona normalmente, logo breve funcionará para quem não estiver logado!\r\n\r\nQualquer problema/bug pode chamar no WhatsApp!', 'urgente', 0, 'sempre', 7, '2026-05-06 14:15:00', 0),
(8, 'Sistema funcionando novamente!', 'Bom dia pessoal!\r\n\r\nResolvi o bug somente agora na parte da noite 05/05/2026 - 22:30h, deu bastante trabalho, não sei oq aconteceu mas precisei reescrever toda a lógica da página de geração de PDF.\r\n\r\nNo momento só está sendo possível gerar relatórios caso estejam logados, quem não tiver conta é só criar uma e entrar que funciona normalmente, logo breve funcionará para quem não estiver logado!\r\n\r\nQualquer problema/bug pode chamar no WhatsApp!', 'urgente', 0, 'sempre', 7, '2026-05-06 14:24:53', 0),
(9, 'Feedback', 'Olá, pessoal! \r\n\r\nGostaria de saber se o gerador já voltou ao normal para quem está utilizando no momento. O feedback de vocês é essencial para garantirmos o funcionamento perfeito da nossa ferramenta.', 'feedback', 0, 'uma_vez', 7, '2026-05-09 18:28:18', 1);
